  // NOTE: vi.stubEnv coerces to string by default, and a 'false' string is
  // still truthy — so we must pass an actual boolean false to flip the ternary
  // `import.meta.env.DEV ? preview : delivery` into the delivery branch.
  // Vitest's stubEnv signature is typed as `string`, so the cast is required
  // at the call site.

  it('uses the PREVIEW token + preview host when DEV is truthy', async () => {
    vi.stubEnv('DEV', true as unknown as string)
    installClient([])
    await reimportContentful()
    expect(createClient).toHaveBeenCalledWith({
      space: 'space-id',
      accessToken: 'preview-token',
      host: 'preview.contentful.com',
    })
  })

  it('uses the DELIVERY token + cdn host when DEV is falsy', async () => {
    vi.stubEnv('DEV', false as unknown as string)
    installClient([])
    await reimportContentful()
    expect(createClient).toHaveBeenCalledWith({
      space: 'space-id',
      accessToken: 'delivery-token',
      host: 'cdn.contentful.com',
    })
  })
})

